206	  // the installed version (from this CLI's package.json) to the registry
207	  // version (`npm view`) and short-circuit when they match.
208	  const currentVersion = readCliVersion();
209	  const latestVersion = await getLatestVersion(execCapture);
210	  if (latestVersion === null) {
211	    logger.warn("Could not check latest pisquad version on registry, skipping self-update");
212	    return { updated: false, reason: "npm view failed" };
213	  }
214	  if (latestVersion === currentVersion) {
215	    logger.info(`pisquad is already up to date (v${currentVersion})`);
216	    return { updated: false, reason: "already latest" };
217	  }
218	  logger.info(`Updating pisquad v${currentVersion} → v${latestVersion}`);
219	  logger.info(`Updating pisquad via npm install -g (timeout ${NPM_TIMEOUT_MS / 1000}s)`);
220	  let result: ExecCaptureResult;
221	  try {
222	    result = await (opts.deps?.runNpmInstallGlobal ?? runNpmInstallGlobal)();
223	  } catch (error) {
224	    const message = error instanceof Error ? error.message : String(error);
225	    throw new Error(`self-update failed: ${message}`);
226	  }
227	
228	  if (result.exitCode !== 0) {
229	    const combined = (result.stderr || result.stdout || "").trim();
230	    const snippet = combined.length > 800 ? `${combined.slice(0, 800)}…` : combined;
231	    throw new Error(
